const CompanyApp=(function(){const a='https://api.connecttag.app/v5/yemenview/initial-data',b='ws9syryf5hyd',c='telecom_companies_cache',d=864e5;return{apiUrl:a,apiKey:b,cacheKey:c,loadFromCache:function(){try{const e=localStorage.getItem(c);if(e){const{data:f,timestamp:g}=JSON.parse(e);if(Date.now()-g<d)return f}}catch(h){console.warn('Cache read error',h)}return null},saveToCache:function(f){try{localStorage.setItem(c,JSON.stringify({data:f,timestamp:Date.now()}))}catch(h){console.warn('Cache write error',h)}},fetchData:function(i,j,k=!1){fetch(a,{method:'GET',headers:{'X-Api-Key':b}}).then(l=>l.json()).then(f=>{if(f.success&&f.result){this.saveToCache(f.result);if(i)i(f.result)}else if(!k&&j)j('عذراً، فشل تحميل البيانات.')}).catch(m=>{console.error('Fetch error:',m);if(!k&&j)j('حدث خطأ في الاتصال بالخادم.')})},getQueryParams:function(){return new URLSearchParams(window.location.search)},showToast:function(n,o=2400){const p=document.getElementById('toast');if(p){p.textContent=n;p.className='toast-msg show';setTimeout(()=>{p.className=p.className.replace('show','')},o)}else if(window.toast){window.toast.show(n,'info')}}}})();